  for name in z.namelist():
    if not name.endswith('.faa.mafft'): continue
    recs=fasta(z.read(name)); seqs=[s for _,s in recs]
    for mode in ('missing','state'):
      v=pis(seqs,mode=='missing')
      if mode=='missing': vals=[len(v)]
      else: vals2=[len(v)]
    rows.append((name,recs,len(pis(seqs,True)),len(pis(seqs,False))))

for mode_i,mode in [(2,'gap-missing'),(3,'gap-state')]:
    print('\\n',mode)
    top=sorted(rows,key=lambda x:-x[mode_i])
    print('max',top[0][mode_i], 'ties',sum(r[mode_i]==top[0][mode_i] for r in rows))
    for n,recs,a,b in top[:30]:
        if (a if mode_i==2 else b)==top[0][mode_i]: print(n, 'taxa='+str(len(recs)),'L='+str(len(recs[0][1])), 'PIS_missing='+str(a),'PIS_gapstate='+str(b), [h for h,_ in recs])
    print('distribution',Counter(r[mode_i] for r in rows).most_common(15))

print('\\nall 4-sequence alignments')
for n,recs,a,b in sorted([r for r in rows if len(r[1])==4], key=lambda x:-x[2]):
    print(n,a,b,len(recs[0][1]),[h for h,_ in recs])
